with exploded as (select id, customer_id, explode(coupon_codes) as value from carts), with_dims as (select a.id, a.customer_id, a.value, b.credit_limit, b.segment from exploded a inner join customers b on a.customer_id = b.id), cleaned as (select id, customer_id, credit_limit, segment, case when segment in ('Consumer', 'SMB') then 'Group A' else 'Other' end segment_group, concat_ws('/', value, segment) value_segment_key, coalesce(segment, 'N/A') resolved_segment from with_dims where customer_id is not null and segment in ('Corporate', 'Consumer', 'SMB')), with_windows as (select id, customer_id, credit_limit, value_segment_key, stddev_samp(credit_limit) over w_recent customer_id_stddev_samp_credit_limit, cume_dist() over w_recent_2 credit_limit_cume_dist, avg(credit_limit) over w_recent customer_id_avg_credit_limit, rank() over (partition by customer_id order by credit_limit desc nulls last) credit_limit_rank, min(credit_limit) over w_recent customer_id_min_credit_limit from cleaned window w_recent as (partition by customer_id), w_recent_2 as (partition by segment order by credit_limit desc nulls first)) select case when credit_limit >= 14800 then 'LARGE' else 'SMALL' end as credit_limit_tier, customer_id, percentile_approx(customer_id_stddev_samp_credit_limit, 0.5) as customer_id_stddev_samp_credit_limit_p50, round(avg(customer_id_min_credit_limit), 2) as avg_customer_id_min_credit_limit, avg(customer_id_min_credit_limit) as avg_customer_id_min_credit_limit_2, avg(credit_limit_rank) as avg_credit_limit_rank from with_windows group by case when credit_limit >= 14800 then 'LARGE' else 'SMALL' end, customer_id order by credit_limit_tier nulls last;
